-- Mensaje 118 · Decir lo que ves no se vale si contradice al cliente (G80). Cerebro v13 → v14 y una regla.
DO $c$ DECLARE v int; BEGIN
  IF EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$ni decir lo que ves —en la práctica lo que ves se imagina—, siempre que no contradiga lo que el cliente ya dijo: si te dijo que está bien surtido, «se ve que le hace falta» es inventar.$v$) > 0) THEN RAISE NOTICE 'El Cerebro ya tiene el 118.'; RETURN; END IF;
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF v <> 13 THEN RAISE EXCEPTION 'se esperaba el Cerebro v13 y está el v%', v; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$ni decir lo que ves —en la práctica lo que ves se imagina—.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado'; END IF;
  INSERT INTO public.doctrina (version, section_key, order_index, title, body, is_active, created_by)
  SELECT v + 1, section_key, order_index, title, replace(body, $v$ni decir lo que ves —en la práctica lo que ves se imagina—.$v$, $v$ni decir lo que ves —en la práctica lo que ves se imagina—, siempre que no contradiga lo que el cliente ya dijo: si te dijo que está bien surtido, «se ve que le hace falta» es inventar.$v$), true, created_by FROM public.doctrina WHERE version = v;
  UPDATE public.doctrina SET is_active = false WHERE is_active AND version = v;
END $c$;

UPDATE public.reglas SET resumen = $v$Fabricar un hueco: venderle un problema que no tiene. LA PRUEBA, en orden. (1) ¿El vendedor contradice lo que el cliente ya dijo —el cliente dijo que está surtido o que no le hace falta, y el vendedor afirma que le falta o que lo necesita—? Entonces es inventar, aunque diga que lo ve. (2) Si no contradice nada: ¿afirma que al cliente le falta algo o que lo necesita sin ninguna base —ni lo dijo el cliente, ni se ve, ni es de su giro, ni lo apoya en negocios como el suyo—? Preguntar nunca es inventar. Apoyarse en otros clientes como él tampoco. Decir lo que ve tampoco (en la práctica se imagina), siempre que no contradiga lo que el cliente dijo.$v$, updated_at = now() WHERE id = 'discovery.hueco_inventado' AND resumen = $v$Fabricar un hueco: venderle un problema que no tiene. LA PRUEBA: ¿el vendedor afirma que al cliente le falta algo o que lo necesita sin ninguna base —ni lo dijo el cliente, ni se ve, ni es de su giro, ni lo apoya en negocios como el suyo—, o contradice lo que el cliente ya dijo? Preguntar nunca es inventar. Apoyarse en otros clientes como él, o decir lo que ve (en la práctica se imagina), tampoco.$v$;

DO $chk$ BEGIN
  IF (SELECT count(*) FROM public.doctrina WHERE is_active) <> 7 OR (SELECT count(DISTINCT version) FROM public.doctrina WHERE is_active) <> 1 THEN RAISE EXCEPTION 'el Cerebro activo no quedó en una sola versión de 7 secciones'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$ni decir lo que ves —en la práctica lo que ves se imagina—, siempre que no contradiga lo que el cliente ya dijo: si te dijo que está bien surtido, «se ve que le hace falta» es inventar.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió el cambio'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.hueco_inventado') IS DISTINCT FROM $v$Fabricar un hueco: venderle un problema que no tiene. LA PRUEBA, en orden. (1) ¿El vendedor contradice lo que el cliente ya dijo —el cliente dijo que está surtido o que no le hace falta, y el vendedor afirma que le falta o que lo necesita—? Entonces es inventar, aunque diga que lo ve. (2) Si no contradice nada: ¿afirma que al cliente le falta algo o que lo necesita sin ninguna base —ni lo dijo el cliente, ni se ve, ni es de su giro, ni lo apoya en negocios como el suyo—? Preguntar nunca es inventar. Apoyarse en otros clientes como él tampoco. Decir lo que ve tampoco (en la práctica se imagina), siempre que no contradiga lo que el cliente dijo.$v$ THEN RAISE EXCEPTION 'la regla no quedó'; END IF;
  IF EXISTS (SELECT 1 FROM public.reglas r WHERE NOT EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0) AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.version = (SELECT max(version) - 1 FROM public.doctrina) AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'una cita de regla ya no está en el Cerebro'; END IF;
END $chk$;
